-- OfferLadder's database in Postgres (local Supabase in Docker; a hosted Supabase
-- project later). The same tables as the browser demo's SQLite database
-- (src/db/schema.sql), with Postgres's stricter types and rules:
--
--   - dates are DATE, times are TIMESTAMP (SQLite keeps both as text)
--   - yes/no columns are BOOLEAN (SQLite uses 1 and 0)
--   - ids count up by themselves (GENERATED BY DEFAULT AS IDENTITY)
--   - the rule set is JSONB, so a query can read one setting out of it
--   - CHECK rules refuse values that can't be right (a quantity of 0, an unknown
--     condition, a discount entered some other way)
--
-- Money is stored in whole cents (199900 = $1,999.00) and percents in basis
-- points (5000 = 50.00%), the same way the engine works, so no rounding creeps in.
--
-- Row-level security is turned on for every table with no rules yet, so nothing
-- is readable through the API until sign-in adds the rules (reps see their own
-- deals, managers their store). The seed script and the tests connect as the
-- database owner, which the rules don't apply to.

-- The two stores.
CREATE TABLE stores (
  id   TEXT PRIMARY KEY,
  name TEXT NOT NULL
);

-- Sales reps. Each one works at one store.
CREATE TABLE reps (
  id       TEXT PRIMARY KEY,
  name     TEXT NOT NULL,
  store_id TEXT NOT NULL REFERENCES stores (id),
  hired_on DATE
);

-- The catalog: one row per product and size (sku = model SKU + size code).
-- Outlet prices are NULL when the product can't be sold as an outlet piece.
CREATE TABLE products (
  sku               TEXT PRIMARY KEY,
  model_sku         TEXT NOT NULL,
  brand             TEXT NOT NULL,
  model             TEXT NOT NULL,
  category          TEXT NOT NULL,            -- mattress, adjustable-base, pillow, ...
  size              TEXT,
  list_cents        INTEGER NOT NULL CHECK (list_cents >= 0),
  cost_cents        INTEGER NOT NULL CHECK (cost_cents >= 0),
  outlet_list_cents INTEGER CHECK (outlet_list_cents >= 0),
  outlet_cost_cents INTEGER CHECK (outlet_cost_cents >= 0)
);

-- Every customer a rep recorded: an "up". Conversion % = sold ups ÷ all ups.
CREATE TABLE visits (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  rep_id     TEXT NOT NULL REFERENCES reps (id),
  store_id   TEXT NOT NULL REFERENCES stores (id),
  visited_on DATE NOT NULL,
  sold       BOOLEAN NOT NULL,                -- true = bought, false = walked
  ticket_id  TEXT                             -- the ticket in the events table
);

-- One row per sale: a snapshot of what the engine worked out on the day, including
-- the commission rate used. Like payroll, changing a rate later never rewrites it.
CREATE TABLE deals (
  id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  visit_id             BIGINT NOT NULL UNIQUE REFERENCES visits (id),  -- one sale per customer
  rep_id               TEXT NOT NULL REFERENCES reps (id),
  store_id             TEXT NOT NULL REFERENCES stores (id),
  closed_on            DATE NOT NULL,
  list_topline_cents   INTEGER NOT NULL,      -- everything at list price
  topline_cents        INTEGER NOT NULL,      -- what the customer paid (pre-tax)
  product_cost_cents   INTEGER NOT NULL,
  delivery_cost_cents  INTEGER NOT NULL,
  gross_cents          INTEGER NOT NULL,      -- profit dollars commission is paid on
  margin_bp            INTEGER NOT NULL,      -- gross ÷ topline
  tier_id              TEXT,                  -- top, middle, low
  rate_bp              INTEGER NOT NULL,      -- commission rate used, bonus included
  attach               BOOLEAN NOT NULL,      -- true = sold an adjustable base
  commission_cents     INTEGER NOT NULL,
  financing_months     INTEGER CHECK (financing_months > 0),  -- NULL = no financing
  financing_adj_cents  INTEGER NOT NULL,      -- + added to gross, − taken out
  delivery_tier_id     TEXT,                  -- NULL = customer took it home
  delivery_price_cents INTEGER NOT NULL CHECK (delivery_price_cents >= 0),
  tax_cents            INTEGER NOT NULL CHECK (tax_cents >= 0),
  offers_made          INTEGER NOT NULL CHECK (offers_made >= 0),
  closed_at_rung       INTEGER NOT NULL CHECK (closed_at_rung >= 0)  -- 0 = asking price
);

-- The items in each sale. net = list − discount.
CREATE TABLE deal_lines (
  deal_id        BIGINT NOT NULL REFERENCES deals (id),
  line_no        INTEGER NOT NULL,
  sku            TEXT NOT NULL REFERENCES products (sku),
  condition      TEXT NOT NULL CHECK (condition IN ('new', 'outlet')),
  qty            INTEGER NOT NULL CHECK (qty > 0),
  list_cents     INTEGER NOT NULL,            -- list price × qty
  discount_cents INTEGER NOT NULL,
  net_cents      INTEGER NOT NULL,            -- what the customer paid for this line
  cost_cents     INTEGER NOT NULL,            -- cost × qty
  locked         BOOLEAN NOT NULL,            -- true = price-locked item
  PRIMARY KEY (deal_id, line_no)
);

-- Every price a rep offered, in order, including offers to customers who walked.
-- step_no 0 is the asking price.
CREATE TABLE offers (
  id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  visit_id             BIGINT NOT NULL REFERENCES visits (id),
  deal_id              BIGINT REFERENCES deals (id),  -- NULL when the customer walked
  step_no              INTEGER NOT NULL CHECK (step_no >= 0),
  topline_cents        INTEGER NOT NULL,
  margin_bp            INTEGER NOT NULL,
  tier_id              TEXT,
  commission_cents     INTEGER NOT NULL,
  accepted             BOOLEAN NOT NULL,      -- true = the customer said yes to this one
  delivery_tier_id     TEXT,                  -- NULL = pickup
  delivery_list_cents  INTEGER,               -- delivery's full price
  delivery_price_cents INTEGER,               -- what the rep charged for it
  financing_months     INTEGER CHECK (financing_months > 0),  -- NULL = no financing
  UNIQUE (visit_id, step_no)
);

-- Every line of every offer: which items, at what price, and how the discount was entered.
CREATE TABLE offer_lines (
  offer_id       BIGINT NOT NULL REFERENCES offers (id),
  line_no        INTEGER NOT NULL,
  sku            TEXT NOT NULL REFERENCES products (sku),
  condition      TEXT NOT NULL CHECK (condition IN ('new', 'outlet')),
  qty            INTEGER NOT NULL CHECK (qty > 0),
  list_cents     INTEGER NOT NULL,
  discount_cents INTEGER NOT NULL,
  net_cents      INTEGER NOT NULL,
  cost_cents     INTEGER NOT NULL,
  locked         BOOLEAN NOT NULL,
  discount_how   TEXT CHECK (discount_how IN ('dollars', 'percent', 'new_price')),  -- NULL = no discount
  discount_scope TEXT CHECK (discount_scope IN ('row', 'ticket')),
  PRIMARY KEY (offer_id, line_no)
);

-- The reasons the rep gave for an offer's discount, one row each (they stack).
CREATE TABLE offer_reasons (
  offer_id  BIGINT NOT NULL REFERENCES offers (id),
  reason_no INTEGER NOT NULL,
  reason    TEXT NOT NULL,                    -- Financing, Military, Google review, ...
  PRIMARY KEY (offer_id, reason_no)
);

-- Usage tracking: one row per meaningful thing a rep did in the app, never every
-- keystroke. Rows are only ever added: the trigger below refuses changes, deletes
-- and emptying the table.
CREATE TABLE events (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  at         TIMESTAMP NOT NULL,              -- store time
  rep_id     TEXT NOT NULL REFERENCES reps (id),
  store_id   TEXT NOT NULL REFERENCES stores (id),
  session_id TEXT NOT NULL,                   -- one sitting (new after 30 quiet minutes)
  ticket_id  TEXT,                            -- one customer's ticket; NULL = not about one
  type       TEXT NOT NULL CHECK (type IN (
               'session_started', 'ticket_started', 'sample_loaded', 'item_added', 'item_removed',
               'discount_applied', 'discount_removed', 'delivery_set', 'financing_set', 'reason_added',
               'floor_refused', 'offer_recorded', 'outcome_recorded', 'ticket_abandoned',
               'gm_calculator_opened', 'inventory_opened', 'lookup_opened')),
  how        TEXT,                            -- sku, search, ...; dollars, percent, new_price; bought, walked
  scope      TEXT,                            -- row, ticket, delivery
  sku        TEXT,                            -- the item involved, if any
  value      INTEGER                          -- a number that goes with it
);

CREATE FUNCTION events_add_only() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  RAISE EXCEPTION 'The events table is add-only: rows can''t be changed or deleted.';
END;
$$;

CREATE TRIGGER events_add_only
BEFORE UPDATE OR DELETE OR TRUNCATE ON events
FOR EACH STATEMENT EXECUTE FUNCTION events_add_only();

-- Customers each rep helped per day, as the store's own count reports them (a door
-- counter or the sales system), not the app. Usage is measured against this.
CREATE TABLE traffic (
  day      DATE NOT NULL,
  rep_id   TEXT NOT NULL REFERENCES reps (id),
  store_id TEXT NOT NULL REFERENCES stores (id),
  ups      INTEGER NOT NULL CHECK (ups >= 0),
  PRIMARY KEY (day, rep_id)
);

-- Each time the manager saves new rules, the whole rule set is kept here.
CREATE TABLE settings_history (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  changed_on    TIMESTAMP NOT NULL,
  settings_json JSONB NOT NULL
);

-- Indexes: like a book's index, they let reports find a rep's or a month's rows
-- without reading the whole table.
CREATE INDEX visits_by_rep_date ON visits (rep_id, visited_on);
CREATE INDEX deals_by_rep_date  ON deals (rep_id, closed_on);
CREATE INDEX offers_by_visit    ON offers (visit_id);
CREATE INDEX events_by_rep_time ON events (rep_id, at);
CREATE INDEX events_by_ticket   ON events (ticket_id);

-- Nothing is readable through the API until sign-in adds rules.
ALTER TABLE stores           ENABLE ROW LEVEL SECURITY;
ALTER TABLE reps             ENABLE ROW LEVEL SECURITY;
ALTER TABLE products         ENABLE ROW LEVEL SECURITY;
ALTER TABLE visits           ENABLE ROW LEVEL SECURITY;
ALTER TABLE deals            ENABLE ROW LEVEL SECURITY;
ALTER TABLE deal_lines       ENABLE ROW LEVEL SECURITY;
ALTER TABLE offers           ENABLE ROW LEVEL SECURITY;
ALTER TABLE offer_lines      ENABLE ROW LEVEL SECURITY;
ALTER TABLE offer_reasons    ENABLE ROW LEVEL SECURITY;
ALTER TABLE events           ENABLE ROW LEVEL SECURITY;
ALTER TABLE traffic          ENABLE ROW LEVEL SECURITY;
ALTER TABLE settings_history ENABLE ROW LEVEL SECURITY;
